        "python3 " + RESTORE_RUNNER_V3_IMPLEMENTATION_AUTHORIZATION_REVIEW_VALIDATOR + " || exit 1",
        "python3 " + FRESH_DISPOSABLE_TARGET_PROVISIONING_AUTHORIZATION_PREPARATION_V3_VALIDATOR + " || exit 1",
        "python3 " + FRESH_DISPOSABLE_TARGET_PROVISIONING_AUTHORIZATION_REVIEW_V3_VALIDATOR + " || exit 1",
